import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"10、【履】 兌下乾上","description":"橫渠易說 - 10、【履】 兌下乾上","frontmatter":{"title":"10、【履】 兌下乾上","description":"橫渠易說 - 10、【履】 兌下乾上"},"headers":[],"relativePath":"classics/hengqu/012.md","filePath":"classics/hengqu/012.md"}'),l={name:"classics/hengqu/012.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_10、【履】-兌下乾上" tabindex="-1">10、【履】 兌下乾上 <a class="header-anchor" href="#_10、【履】-兌下乾上" aria-label="Permalink to “10、【履】 兌下乾上”">​</a></h1><h3 id="彖曰-履-柔履剛也。說而應乎乾-是以履虎尾-不咥人-亨。" tabindex="-1">彖曰：履，柔履剛也。說而應乎乾，是以履虎尾，不咥人，亨。 <a class="header-anchor" href="#彖曰-履-柔履剛也。說而應乎乾-是以履虎尾-不咥人-亨。" aria-label="Permalink to “彖曰：履，柔履剛也。說而應乎乾，是以履虎尾，不咥人，亨。”">​</a></h3><p>說雖應乾而二不累五也。剛中正，履帝位而不疚，光明也。 無陰柔之累，故不疚，此所以正一卦之德也。</p><h3 id="象曰-上天下澤-履-君子以辯上下-定民志。" tabindex="-1">象曰：上天下澤，履，君子以辯上下，定民志。 <a class="header-anchor" href="#象曰-上天下澤-履-君子以辯上下-定民志。" aria-label="Permalink to “象曰：上天下澤，履，君子以辯上下，定民志。”">​</a></h3><h3 id="初九-素履-往無咎。-象曰-素履之往-獨行願也。" tabindex="-1">初九，素履，往無咎。 象曰：素履之往，獨行願也。 <a class="header-anchor" href="#初九-素履-往無咎。-象曰-素履之往-獨行願也。" aria-label="Permalink to “初九，素履，往無咎。 象曰：素履之往，獨行願也。”">​</a></h3><p>陰累不乾，無應於上，故其履潔素。</p><h3 id="九二-履道坦坦-幽人貞吉。-象曰-幽人貞吉-中不自亂也。" tabindex="-1">九二，履道坦坦，幽人貞吉。 象曰：“幽人貞吉”，中不自亂也。 <a class="header-anchor" href="#九二-履道坦坦-幽人貞吉。-象曰-幽人貞吉-中不自亂也。" aria-label="Permalink to “九二，履道坦坦，幽人貞吉。 象曰：“幽人貞吉”，中不自亂也。”">​</a></h3><p>中正不累，無援於上，故中不自亂，得幽人之正。</p><h3 id="六三-眇能視-跛能履。履虎尾-咥人兇。武人為於六君。-象曰-眇能視-不足以有明也-跛能履-不足以與行也。咥人之兇-位不當也。-武人為於大君-志剛也。" tabindex="-1">六三，眇能視，跛能履。履虎尾，咥人兇。武人為於六君。 象曰：“眇能視”，不足以有明也；“跛能履”，不足以與行也。咥人之兇，位不當也。“武人為於大君”，志剛也。 <a class="header-anchor" href="#六三-眇能視-跛能履。履虎尾-咥人兇。武人為於六君。-象曰-眇能視-不足以有明也-跛能履-不足以與行也。咥人之兇-位不當也。-武人為於大君-志剛也。" aria-label="Permalink to “六三，眇能視，跛能履。履虎尾，咥人兇。武人為於六君。 象曰：“眇能視”，不足以有明也；“跛能履”，不足以與行也。咥人之兇，位不當也。“武人為於大君”，志剛也。”">​</a></h3><p>大君者，為眾爻之主也。武人者，剛而不德也。</p><h3 id="九四-履虎尾愬愬-終吉。-象曰-愬愬終吉-志行也。" tabindex="-1">九四，履虎尾愬愬，終吉。 象曰：“愬愬終吉”，志行也。 <a class="header-anchor" href="#九四-履虎尾愬愬-終吉。-象曰-愬愬終吉-志行也。" aria-label="Permalink to “九四，履虎尾愬愬，終吉。 象曰：“愬愬終吉”，志行也。”">​</a></h3><p>三五不累於己，處多懼之地，近比於三，能常自危，則志願終吉。陽居陰，故不自肆，常自危也。</p><h3 id="九五-夬履貞厲-象曰-夬履貞厲-位正當也。" tabindex="-1">九五，“夬履貞厲”， 象曰：“夬履貞厲”，位正當也。 <a class="header-anchor" href="#九五-夬履貞厲-象曰-夬履貞厲-位正當也。" aria-label="Permalink to “九五，“夬履貞厲”， 象曰：“夬履貞厲”，位正當也。”">​</a></h3><h3 id="上九-視履考祥-其旋元吉。-象曰-元吉在上-大有慶也。" tabindex="-1">上九，視履考祥，其旋元吉。 象曰：元吉在上，大有慶也。 <a class="header-anchor" href="#上九-視履考祥-其旋元吉。-象曰-元吉在上-大有慶也。" aria-label="Permalink to “上九，視履考祥，其旋元吉。 象曰：元吉在上，大有慶也。”">​</a></h3><p>視所履以考求其吉，莫如旋而及下，則獲應而有喜也。 乘剛未安，其進也寧旋。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
